<?php require "../config.php";if(empty($_SESSION["admin"])){header("Location: login.php");exit;}$id=(int)$_GET["id"];if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$pdo->prepare("UPDATE emergency_reports SET status=? WHERE id=?");$s->execute([$_POST["status"],$id]);header("Location: dashboard.php");exit;}?><!doctype html><html><head><title>Update Status</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="form panel"><h2>Update Emergency Status</h2><form method="post"><select name="status"><option>Pending</option><option>Assigned</option><option>In Progress</option><option>Resolved</option><option>Cancelled</option></select><button class="btn">Update</button></form></div></body></html>